import {taskDefaults,isClosedProject} from './workflow-rules.js';
export const STAGES=['Assessment & Planning','ECN DD Review','Execution & Testing','ECN IMP Review','MP'];
export const HEALTH=['On Track','At Risk','Delayed','On Hold'];
export const KINDS=['Assessment','Execution','Test','Approval'];
export const ISSUE_STATES=['Open','In Recovery','Pending Verification','Closed'];
export const person=(s,id)=>s.people.find(p=>p.id===id);
export const project=(s,id)=>s.projects.find(p=>p.id===id);
export const done=t=>t.ownerIds.length>0 && t.completedBy.length>=t.ownerIds.length;
export const taskStatus=(t,today)=>done(t)?'Complete':t.due<today?'Overdue':t.startedAt?'In Progress':t.start>today?'Upcoming':'Scheduled';
export const activeIssue=i=>i.status!=='Closed';
export const tasksFor=(s,id)=>s.tasks.filter(t=>t.projectId===id);
export const issuesFor=(s,id)=>s.issues.filter(i=>i.projectId===id);
export function projectMetrics(s,id){const ts=tasksFor(s,id);return {total:ts.length,done:ts.filter(done).length,overdue:ts.filter(t=>!done(t)&&t.due<s.scenarioDate).length,openIssues:issuesFor(s,id).filter(activeIssue).length,skus:s.projectSkus.filter(x=>x.projectId===id&&x.active).length};}
export function reportProjects(s,{projectIds=[],programId='',department='',health=''}={}){return s.projects.filter(p=>(!projectIds.length||projectIds.includes(p.id))&&(!programId||p.programId===programId)&&(!health||p.health===health)&&(!department||s.tasks.some(t=>t.projectId===p.id&&t.workstream===department)||s.issues.some(i=>i.projectId===p.id&&i.department===department)));}
export function reportRows(s,filter){return reportProjects(s,filter).map(p=>({id:p.id,name:p.name,program:s.programs.find(g=>g.id===p.programId)?.name||'Unassigned',stage:p.stage,health:p.health,lead:person(s,p.leadId)?.name||'',factory:p.factory,targetMP:p.targetMP,...projectMetrics(s,p.id),summary:p.summary}));}
const text=v=>typeof v==='string'?v.trim():'';
const requireThat=(condition,message)=>{if(!condition)throw new Error(message);};
const uid=p=>p+'-'+crypto.randomUUID().slice(0,10);
const get=(a,id,label)=>{const v=a.find(x=>x.id===id);requireThat(v,`${label} was not found.`);return v;};
function validateTask(s,t){requireThat(t.title&&t.title.length<=250,'Enter a task name (up to 250 characters).');get(s.projects,t.projectId,'Project');t.ownerIds.forEach(id=>get(s.people,id,'Owner'));requireThat(/^\d{4}-\d{2}-\d{2}$/.test(t.start)&&/^\d{4}-\d{2}-\d{2}$/.test(t.due),'Enter the start and due dates.');requireThat(t.start<=t.due,'Due date cannot be before the start date.');requireThat(KINDS.includes(t.kind),'Choose a valid work type.');for(const id of [...t.predecessorIds,...t.sourceAssessmentIds]){const linked=get(s.tasks,id,'Linked task');requireThat(id!==t.id&&linked.projectId===t.projectId,'Linked tasks must be other tasks in this project.');}for(const id of t.sourceAssessmentIds)requireThat(get(s.tasks,id,'Assessment').kind==='Assessment','The source must be an assessment task.');const walk=(id,path)=>{requireThat(!path.has(id),'This dependency would create a cycle.');const n=new Set(path);n.add(id);for(const prev of get(s.tasks,id,'Predecessor').predecessorIds)walk(prev,n);};walk(t.id,new Set());}
export function applyOperation(original,op){
 const s=structuredClone(original);requireThat(op.mode!=='viewer','Viewer mode is read only. Switch to Contributor or Maintainer to make a change.');get(s.people,op.actorId,'Person');let id=op.id,label='',entity='';const values=op.values||{};
 if(op.type==='updateTask'){
  const t=get(s.tasks,id,'Task');const allowed=['title','ownerIds','kind','phase','workstream','start','due','priority','brief','outcome','assessmentDecision','testResult','approvalStatus','approvalDate','predecessorIds','sourceAssessmentIds','duration','durationBasis'];for(const k of allowed)if(k in values)t[k]=values[k];validateTask(s,t);if('confirmOwnPart' in values){requireThat(t.ownerIds.includes(op.actorId),'Only a listed owner can confirm their part.');t.completedBy=values.confirmOwnPart?[...new Set([...t.completedBy,op.actorId])]:t.completedBy.filter(x=>x!==op.actorId);}label='Updated task';entity='task';
 }else if(op.type==='confirmTask'){
  const t=get(s.tasks,id,'Task');requireThat(t.ownerIds.includes(op.actorId),'Only a listed owner can confirm their part.');t.completedBy=t.completedBy.includes(op.actorId)?t.completedBy.filter(p=>p!==op.actorId):[...t.completedBy,op.actorId];label=t.completedBy.includes(op.actorId)?'Confirmed own part':'Reopened own part';entity='task';
 }else if(op.type==='createTask'){
  const p=get(s.projects,values.projectId,'Project');requireThat(!isClosedProject(p),'Reopen the project before adding new tasks.');const defaults=taskDefaults(s,{...values,actorId:op.actorId});id=uid('task');const t={id,projectId:values.projectId,title:text(values.title),ownerIds:values.ownerIds||defaults.ownerIds,completedBy:[],kind:values.kind||defaults.kind,phase:values.phase||defaults.phase,workstream:values.workstream||defaults.workstream,start:values.start||s.scenarioDate,due:values.due||s.scenarioDate,priority:values.priority||'Normal',brief:text(values.brief),outcome:'',assessmentDecision:'',testResult:'Not Reported',approvalStatus:'Not Submitted',approvalDate:'',predecessorIds:values.predecessorIds||[],sourceAssessmentIds:values.sourceAssessmentIds||[],duration:5,durationBasis:'Working Days',deliverableId:''};s.tasks.push(t);validateTask(s,t);label='Created task';entity='task';
 }else if(op.type==='updateProject'){
  const p=get(s.projects,id,'Project');for(const k of ['name','scope','summary','stage','health','leadId','factory','priority','targetMP','team'])if(k in values)p[k]=values[k];requireThat(text(p.name),'Enter a project name.');get(s.people,p.leadId,'Project lead');p.team.forEach(x=>get(s.people,x,'Team member'));requireThat(p.team.includes(p.leadId),'Include the project lead in the team.');requireThat(STAGES.includes(p.stage)&&HEALTH.includes(p.health),'Choose a valid stage and health.');label='Updated project';entity='project';
 }else if(op.type==='createProject'){
  id=text(values.id);requireThat(id&&!s.projects.some(p=>p.id.toLowerCase()===id.toLowerCase()),'Use a new, unique project ID.');get(s.programs,values.programId,'Program');get(s.people,values.leadId,'Project lead');requireThat(text(values.name)&&text(values.factory),'Enter the project name and factory.');const p={id,name:text(values.name),programId:values.programId,leadId:values.leadId,factory:text(values.factory),scope:text(values.scope),type:values.type||'Extension',priority:'Normal',stage:STAGES[0],health:'On Track',targetMP:values.targetMP||'',summary:'Initial departmental assessments are ready to assign.',team:[...new Set([values.leadId,...(values.team||[])])],lifecycle:'Active',documentIds:[],source:'Created in local design sandbox'};s.projects.push(p);
  for(const spec of (values.skuNames||'').split(',').map(text).filter(Boolean)){const sku={id:uid('sku'),name:spec,programId:p.programId,market:'To confirm'};s.skus.push(sku);s.projectSkus.push({id:uid('ps'),projectId:id,skuId:sku.id,status:'In Development',active:true,overrideDate:'',overrideReason:''});}
  if(values.applyTemplate!==false){const depts=['NPI','Packaging','CMF / ID','DQTP','EE','Compliance','Tooling','NPD','ME','SC','Factory'];for(const d of depts){const matching=p.team.filter(id=>person(s,id)?.department===d);const owners=matching.length===1?matching:[];const t={id:uid('task'),projectId:id,title:d==='NPI'?'Review RKO and change PPT':d+' change assessment',ownerIds:owners,completedBy:[],workstream:d,kind:'Assessment',phase:STAGES[0],start:s.scenarioDate,due:s.scenarioDate,priority:'Normal',brief:'Review the agreed change scope. Record required work, expected duration, resources and supporting documents.',outcome:'',assessmentDecision:'Needs Information',testResult:'Not Reported',approvalStatus:'',approvalDate:'',predecessorIds:[],sourceAssessmentIds:[],duration:5,durationBasis:'Working Days',deliverableId:''};s.tasks.push(t);}}
  label='Created project and assessment plan';entity='project';
 }else if(op.type==='createIssue'||op.type==='updateIssue'){
  let i;if(op.type==='createIssue'){id=uid('ISS');i={id,projectId:values.projectId,title:'',details:'',department:person(s,op.actorId).department,ownerId:op.actorId,severity:'Medium',status:'Open',category:'Technical',impact:'',impactMP:false,due:s.scenarioDate,occurred:s.scenarioDate,phase:project(s,values.projectId)?.stage||STAGES[0],rootCause:'',resolution:'',closedDate:'',prevention:'',affectedProjectSkuIds:[],relatedTaskIds:[]};s.issues.push(i);}else i=get(s.issues,id,'Issue');const before=i.status;for(const k of ['title','details','department','ownerId','severity','status','category','impact','impactMP','due','phase','rootCause','resolution','prevention','affectedProjectSkuIds','relatedTaskIds','returnReason'])if(k in values)i[k]=values[k];get(s.projects,i.projectId,'Project');get(s.people,i.ownerId,'Owner');requireThat(text(i.title)&&text(i.details),'Enter an issue title and what happened.');requireThat(ISSUE_STATES.includes(i.status),'Choose a valid issue status.');if(['Closed','Pending Verification'].includes(i.status)){requireThat(text(i.resolution),'Record the actual resolution before closing the issue.');requireThat(!s.actions.some(a=>a.issueId===i.id&&!['Done','Cancelled'].includes(a.status)),'Finish or cancel the remaining recovery actions before closing the issue.');}const verifier=i.verifierId||get(s.projects,i.projectId,'Project').leadId;if(i.status==='Closed'&&before!=='Closed')requireThat(op.actorId===verifier,'Only the project lead or assigned reviewer can confirm closure.');if(i.status==='Pending Verification'&&before!==i.status){requireThat([i.ownerId,verifier].includes(op.actorId),'Only the issue lead can submit the resolution.');i.submittedBy=op.actorId;i.submittedAt=new Date().toISOString();}if(before==='Pending Verification'&&i.status==='In Recovery'){requireThat(op.actorId===verifier,'Only the reviewer can return the resolution.');requireThat(text(values.returnReason),'Describe what still needs to be resolved.');}i.affectedProjectSkuIds.forEach(x=>requireThat(get(s.projectSkus,x,'Project SKU').projectId===i.projectId,'The affected SKU must belong to this project.'));i.relatedTaskIds.forEach(x=>requireThat(get(s.tasks,x,'Task').projectId===i.projectId,'The affected task must belong to this project.'));if(i.status==='Closed'&&before!=='Closed'){i.closedDate=s.scenarioDate;i.closedBy=op.actorId;i.closedAt=new Date().toISOString();}if(i.status!=='Closed'&&before==='Closed'){i.closedDate='';i.closedBy='';i.closedAt='';}label=before!==i.status?`Issue status: ${before} → ${i.status}`:'Updated issue';entity='issue';
 }else if(op.type==='createAction'||op.type==='updateAction'){
  let a;if(op.type==='createAction'){id=uid('action');a={id,issueId:values.issueId,title:'',ownerId:op.actorId,due:s.scenarioDate,status:'Open',result:'',evidenceUrl:'',formalTaskId:''};s.actions.push(a);}else a=get(s.actions,id,'Action');for(const k of ['title','ownerId','due','status','result','evidenceUrl'])if(k in values)a[k]=values[k];const issue=get(s.issues,a.issueId,'Issue');requireThat(issue.status!=='Closed','Reopen the issue before changing its actions.');get(s.people,a.ownerId,'Owner');requireThat(text(a.title)&&a.due,'Enter the action and due date.');if(a.evidenceUrl)requireThat(/^https?:\/\//.test(a.evidenceUrl),'Use an http or https evidence link.');label='Updated recovery action';entity='action';
 }else if(op.type==='saveLesson'){
  const issue=get(s.issues,values.issueId,'Issue');requireThat(issue.status==='Closed'&&text(issue.resolution),'Resolve the issue before saving its lesson.');requireThat(text(values.summary),'Add a useful prevention or lesson.');let l=s.lessons.find(x=>x.issueId===issue.id);if(!l){l={id:uid('lesson'),issueId:issue.id,useCount:0};s.lessons.push(l);}Object.assign(l,{title:text(values.title)||issue.title,summary:text(values.summary),department:issue.department,category:issue.category,created:s.scenarioDate});id=l.id;label='Saved lesson';entity='lesson';
 }else if(op.type==='reuseLesson'){
  const l=get(s.lessons,id,'Lesson');get(s.projects,values.projectId,'Project');const p=get(s.projects,values.projectId,'Project');const t={id:uid('task'),projectId:p.id,title:'Prevent recurrence: '+l.title,ownerIds:[p.leadId],completedBy:[],kind:'Execution',phase:p.stage,workstream:l.department,start:s.scenarioDate,due:s.scenarioDate,priority:'Normal',brief:l.summary+'\nSource issue: '+l.issueId,outcome:'',assessmentDecision:'',testResult:'Not Reported',approvalStatus:'',approvalDate:'',predecessorIds:[],sourceAssessmentIds:[],duration:1,durationBasis:'Working Days',deliverableId:''};s.tasks.push(t);l.useCount++;id=t.id;label='Added lesson to project plan';entity='task';
 }else if(op.type==='saveReport'){
  const rows=reportRows(s,values.filter||{});requireThat(rows.length,'Choose a scope with at least one project.');id=uid('report');s.reports.push({id,title:text(values.title)||'Project status snapshot',filter:values.filter||{},rows,createdAt:new Date().toISOString(),actorId:op.actorId,scenarioDate:s.scenarioDate});label='Saved report snapshot';entity='report';
 }else if(op.type==='updateSku'){
  const ps=get(s.projectSkus,id,'Project SKU');for(const k of ['status','overrideDate','overrideReason'])if(k in values)ps[k]=values[k];requireThat(!ps.overrideDate||text(ps.overrideReason),'Explain the SKU date exception.');label='Updated project SKU';entity='sku';
 }else if(op.type==='createDocument'){
  const p=get(s.projects,values.projectId,'Project');requireThat(text(values.name),'Enter a document name.');requireThat(!values.url||/^https?:\/\//.test(values.url),'Use an http or https document link.');id=uid('doc');s.documents.push({id,projectId:p.id,name:text(values.name),version:text(values.version)||'v1',type:'reference',url:values.url||'',content:text(values.content),updated:s.scenarioDate,ownerId:op.actorId});p.documentIds.push(id);label='Added project document';entity='document';
 }else throw new Error('Unknown operation.');
 const time=new Date().toISOString();const collection={task:s.tasks,project:s.projects,issue:s.issues,action:s.actions,sku:s.projectSkus};collection[entity]?.filter(x=>x.id===id).forEach(x=>x.updatedAt=time);s.history.push({id:uid('event'),entity,entityId:id,label,actorId:op.actorId,at:time,...(entity==='issue'?{status:get(s.issues,id,'Issue').status,resolution:get(s.issues,id,'Issue').resolution,returnReason:values.returnReason||''}:{}),projectId:entity==='project'?id:entity==='task'?get(s.tasks,id,'Task').projectId:entity==='issue'?get(s.issues,id,'Issue').projectId:entity==='action'?get(s.issues,get(s.actions,id,'Action').issueId,'Issue').projectId:entity==='sku'?get(s.projectSkus,id,'SKU').projectId:''});s.revision++;return {state:s,id,entity,label};
}
